<label>Instruksi <?= e($label) ?><textarea name="<?= $key ?>_instructions" rows="4" maxlength="2000" required><?= e($settings[$key.'_instructions']) ?></textarea></label></fieldset>
<?php endforeach; ?><button class="btn btn-dark" type="submit">Simpan pengaturan pembayaran</button></form></section>

